def sumofFactors(n):
    def is_even(num):
        return num % 2 == 0

    sum_even_factors = 0
    for i in range(1, n + 1):
        if n % i == 0 and is_even(i):
            sum_even_factors += i
    return sum_even_factors

# Example usage and test
assert sumofFactors(18) == 26
