def merge_dictionaries_three(dict1, dict2, dict3):
    result = {}
    # Iterate through each dictionary and merge the key-value pairs
    for d in (dict1, dict2, dict3):
        for key, value in d.items():
            # Update the dictionary only if the key doesn't already exist
            if key not in result:
                result[key] = value
    return result

# Test cases
assert merge_dictionaries_three(
    {"R": "Red", "B": "Black", "P": "Pink"},
    {"G": "Green", "W": "White"},
    {"O": "Orange", "W": "White", "B": "Black"}
) == {'B': 'Black', 'R': 'Red', 'P': 'Pink', 'G': 'Green', 'W': 'White', 'O': 'Orange'}

assert merge_dictionaries_three(
    {"R": "Red", "B": "Black", "P": "Pink"},
    {"G": "Green", "W": "White"},
    {"L": "lavender", "B": "Blue"}
) == {'R': 'Red', 'B': 'Black', 'P': 'Pink', 'G': 'Green', 'W': 'White', 'L': 'lavender'}
